        print('  ',card,b.get('http'),b.get('delaySeconds',''),r.get('productName'),r.get('statementDate'),r.get('lastPayDate'),r.get('nextStatementDate'),r.get('statementPaymentStatus'),r.get('automaticPaymentFlag'))
        for x in blk: print('      ',x)
    for card,b in s.get('statement.week.get',{}).items():
