cd /Users/omerf/Desktop/hackathonfreya; python3 - <<'EOF'
import json
d=json.load(open('case/test-environment/test-customers.json'))
def walk(o,path):
    if isinstance(o,dict):
        if 'http' in o and 'response' in o:
            r=o['response']; dd=r.get('data') if isinstance(r,dict) else None
            notes=[]
            if o['http']!=200: notes.append('HTTP %s %s'%(o['http'],r.get('result',{}).get('code')))
            if 'delaySeconds' in o: notes.append('DELAY %s'%o['delaySeconds'])
            if isinstance(dd,dict):
                for k in ['statementDate','lastPayDate','nextStatementDate','nextLastPayDate']:
                    if k in dd and not dd[k]: notes.append('EMPTY '+k)
                if 'debtTL' in dd:
                    for k in ['debtUSD','debtEUR','debtGBP']:
                        if k not in dd: notes.append('MISSING '+k)
                        elif not dd[k]: notes.append('EMPTYBLK '+k)
                    for k in ['debtTL','debtUSD','debtEUR','debtGBP']:
                        x=dd.get(k) or {}
                        if x.get('transferAmount'): notes.append('TRANSFER %s %s'%(k,x['transferAmount']))
                        if (x.get('totalDebt') or 0)<0: notes.append('NEG %s'%k)
                        if x.get('remainAutomaticPaymentAmount'): notes.append('AP %s %s'%(k,x['remainAutomaticPaymentAmount']))
                        if x and x.get('statementPaymentStatus')=='NO_DEBT' and x.get('totalDebt',0)>0: notes.append('NODEBT_BUT_TOTAL %s %s'%(k,x['totalDebt']))
                    if dd.get('automaticPaymentFlag')=='Y': notes.append('AUTOPAY Y')
                    if dd.get('statementPaymentStatus')=='NO_DEBT': notes.append('CARD NO_DEBT')
                    if dd.get('lastPayDate','x')[:2] and dd.get('statementDate') not in ('05.10.2026',): notes.append('sd=%s lp=%s'%(dd.get('statementDate'),dd.get('lastPayDate')))
                if 'productName' in dd and not dd['productName']: notes.append('EMPTY NAME')
                if 'cards' in dd:
                    for c in dd['cards']:
                        if not c.get('isMainCard'): notes.append('NOTMAIN '+c['cardNumber'])
                if dd.get('responseCode') not in (None,0) or dd.get('exitState') not in (None,'OK','DONE','Done','1_CARD','MULTI_CARD'): notes.append('ODD %s %s'%(dd.get('responseCode'),dd.get('exitState')))
            if notes: print(path, notes)
            return
        for k,v in o.items(): walk(v,path+'/'+k)
for c in d['customers']: walk(c['services'],c['customerNo'])
