# ---------------------------------------------------------------- state helpers
def speak(text):
    vars['say'] = ' '.join(text.split())
    vars['route'] = 'talk'


def ask(prefix, q, qs, stage):
    full = (prefix + ' ' + q).strip()
    vars['q'] = q
    vars['q_short'] = qs or q
    vars['stage'] = stage
    vars['tries'] = '0'
    vars['last_full'] = full
    speak(full)


def reask(prefix='', count=True, short=False):
    if count:
        t = gi('tries') + 1
        vars['tries'] = str(t)
        if t >= 3:
            finish(S_FAIL3, 'menu')
            return
    q = g('q_short') if short else g('q')
    full = (prefix + ' ' + q).strip()
    vars['last_full'] = full
    speak(full)


def finish(text, kind):
    vars['stage'] = 'closing'
    vars['end_kind'] = kind
    vars['q'] = ''
    vars['q_short'] = ''
    vars['last_full'] = text
    speak(text)


def go_api(name):
    vars['pending'] = name
    vars[name + '_pack'] = ''
    vars['route'] = 'api_' + name


def result_of(name):
    try:
        p = json.loads(g(name + '_pack') or 'null')
    except Exception:
        p = None
    if not isinstance(p, dict):
        return (False, None, g(name + '_status_code'))
    b = p.get('b')
    st = str(p.get('s') or '')
    if isinstance(b, dict):
        r = b.get('result') if isinstance(b.get('result'), dict) else dict()
        if str(r.get('returnCode', '')) == '1' and isinstance(b.get('data'), dict):
            return (True, b.get('data'), st)
    return (False, None, st)


def cards():
