    else:
        q = 'Hesap kesim tarihinizi değiştirebilirim.'
    ask(pre, q, q, 'offer')


# ---------------------------------------------------------------- e-mail
def short_addr(a):
    a = (a or '').strip()
    if '@' not in a:
        return a
    local, dom = a.split('@', 1)
    messy = len(local) > 14 or bool(re.search(r'[0-9_\-+]', local)) or local.count('.') > 1
    if not messy:
        return a
    dn = dom.split('.')[0]
    if dn.lower() in ('gmail', 'hotmail', 'outlook', 'yahoo', 'icloud', 'yandex'):
        dn = dn[:1].upper() + dn[1:]
    return local[:1].lower() + ' ile başlayan ' + dn + ' adresiniz'


def email_question():
    a = g('email_addr')
    sa = short_addr(a)
    if sa == a:
        return 'Ekstrenizi ' + a + ' adresine göndermemi ister misiniz?'
    return 'Ekstrenizi kayıtlı ' + sa + 'e göndermemi ister misiniz?'


def start_email(pre=''):
    st = g('email_state')
    if st == '':
        vars['want'] = 'email'
        vars['offer_prefix'] = pre
        go_api('email_get')
        return
    if st == 'fail':
        finish((pre + ' ' + S_SVC).strip(), 'agent')
        return
    if st == 'none':
        if g('week_done') != '1':
            ask((pre + ' ' + S_NO_EMAIL).strip(), 'Hesap kesim tarihinizi değiştirebilirim.',
                'Hesap kesim tarihinizi değiştirebilirim.', 'offer')
        else:
            finish((pre + ' ' + S_NO_EMAIL + ' ' + S_MENU).strip(), 'menu')
        return
    if gi('sends') >= 3:
        finish((pre + ' ' + S_MENU).strip(), 'menu')
        return
    if pdate(g('stmt_date')) is None:
        c = cur()
        if not c.get('num'):
            # no card read yet: settle the card first
            vars['want'] = 'email'
            pick_or_read(pre)
            return
        finish((pre + ' Kartınızın henüz kesilmiş bir ekstresi bulunmadığı için gönderebileceğim bir ekstre yok. ' + S_MENU).strip(), 'menu')
        return
    q = email_question()
    ask(pre, q, q, 'email_confirm')


# ---------------------------------------------------------------- statement week
def start_week(pre=''):
    c = cur()
    if not c.get('num'):
        vars['want'] = 'week'
        pick_or_read(pre)
        return
    if g('week_done') == '1':
        finish((pre + ' Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz ve bu yıl değişiklik yapıldı. ' + S_MENU).strip(), 'menu')
        return
    vars['week_prefix'] = pre
    vars['req_card'] = c.get('num', '')
    go_api('week_get')


def week_options_q():
    cw = gi('wk_cur')
    opts = [ORD[i] for i in (1, 2, 3, 4) if i != cw]
    return 'Hesap kesim tarihinizi ayın ' + join_tr(opts).replace(' ve ', ' ya da ') + ' haftasına alabilirim. Hangisini tercih edersiniz?'


def joint_effect():
    rel = g('wk_rel')
    rn = g('wk_relname') or 'diğer'
    if rel == 'M':
        return 'Bu değişiklik kartınıza bağlı ' + rn + ' kartınızı da etkileyecek.'
    if rel == 'C':
        return 'Bu değişiklik kartınızın bağlı olduğu ' + rn + ' kartınızı da etkileyecek.'
    return ''


def preview(week, pre=''):
    vars['wk_new'] = str(week)
    vars['req_week'] = str(week)
    vars['req_day'] = g('wk_day')
    vars['req_card'] = cur().get('num', '')
    vars['week_prefix'] = pre
    go_api('week_decide')


def confirm_q():
    return ('Yeni hesap kesim haftanız her ayın ' + ORD[gi('wk_new')] + ' haftası olacak. Yeni hesap kesim tarihiniz '
            + sdate(g('wk_new_sd')) + ', son ödeme tarihiniz ' + sdate(g('wk_new_due')) + ' olacak. Onaylıyor musunuz?')


def pick_or_read(pre=''):
    el = eligible()
    if not el:
        finish(S_NOCARD, 'menu')
        return
    if len(el) == 1:
        start_read(el[0], pre)
        return
    ask_pick(pre, unread() or el)


# ---------------------------------------------------------------- API results
def handle_result(name):
    ok, data, st = result_of(name)
    if name == 'cards_list':
        if not ok:
            if st == '404':
                finish(S_NOCARD, 'menu')
            else:
                finish(S_SVC, 'agent')
            return
        lst = []
        for x in (data.get('cards') or []):
            if not isinstance(x, dict):
                continue
            num = str(x.get('cardNumber') or '')
            l4 = str(x.get('cardNumberLast4') or num[-4:])
            mc = x.get('isMainCard')
            main = not (mc is False or str(mc).lower() == 'false')
            lst.append(dict(num=num, l4=l4, name=safe_name(x.get('productName')), main=main))
        vars['cards_json'] = json.dumps(lst)
        el = [c for c in lst if c.get('main')]
        if not el:
            finish(S_NOCARD, 'menu')
            return
        pre = g('start_prefix')
        if len(el) == 1:
            start_read(el[0], pre)
            return
        txt = g('first_card_text')
        ds = g('first_digits')
        vars['cand_json'] = json.dumps([c.get('num') for c in el])
        if txt or ds:
            pool = el
            found = digit_match(ds, pool) if ds else name_match(txt, pool)
            if len(found) == 1:
                start_read(found[0], pre)
                return
        ask_pick(pre, el)
        return
    if name == 'cards_balance':
        if not ok:
            finish((g('read_prefix') + ' ' + S_SVC).strip(), 'agent')
            return
        text, nodebt = compose_reading(data, cur())
        after_reading(text, nodebt)
        return
    if name == 'email_get':
        if not ok:
            vars['email_state'] = 'fail'
        else:
            a = str(data.get('ibanEmail') or '').strip()
            ct = str(data.get('communicationType') or '')
            if a and '@' in a and ct.lower() != 'phone':
                vars['email_state'] = 'ok'
                vars['email_addr'] = a
            else:
                vars['email_state'] = 'none'
        pre = g('offer_prefix')
        vars['offer_prefix'] = ''
        if g('want') == 'email':
            vars['want'] = ''
            start_email(pre)
            return
        if g('email_state') == 'fail':
            # the e-mail option cannot be offered; the week change still can
            if g('week_done') != '1':
                ask(pre, 'Hesap kesim tarihinizi değiştirebilirim.', 'Hesap kesim tarihinizi değiştirebilirim.', 'offer')
            else:
                finish((pre + ' ' + S_MENU).strip(), 'menu')
            return
        offer(pre)
        return
    if name == 'week_get':
        pre = g('week_prefix')
        if not ok:
            finish((pre + ' ' + S_WEEK_SVC).strip(), 'agent')
            return
        c = cur()
        vars['wk_cur'] = str(gi_val(data.get('statementWeek')))
        vars['wk_day'] = str(data.get('statementDay') or '')
        rel = str(data.get('relationType') or '').strip().upper()
        vars['wk_rel'] = rel if rel in ('M', 'C') else ''
        vars['wk_relname'] = safe_name(data.get('relatedCardProductName'))
        rnum = str(data.get('relatedCardNumber') or '')
        rl4 = rnum[-4:] if len(rnum) >= 4 else ''
        nsd = str(data.get('nextStatementDate') or '')
        nlp = str(data.get('nextLastPayDate') or '')
        cw = gi('wk_cur')
        wk_txt = ORD[cw] if 1 <= cw <= 4 else ''
        if vars.get('wk_rel') == 'M':
            other = ('sonu ' + l4w(rl4) + ' ile biten ' + g('wk_relname')).strip()
            s = intro(c) + ' ile buna bağlı ' + other + ' kartınızın ortak hesap kesim tarihi her ayın ' + wk_txt + ' haftası olarak tanımlı.'
        elif vars.get('wk_rel') == 'C':
            other = ('sonu ' + l4w(rl4) + ' ile biten ' + g('wk_relname')).strip()
            s = intro(c) + ' ile bu kartın bağlı olduğu ' + other + ' kartınızın ortak hesap kesim tarihi her ayın ' + wk_txt + ' haftası olarak tanımlı.'
        else:
            s = intro(c) + 'ın hesap kesim tarihi her ayın ' + wk_txt + ' haftası olarak tanımlı.'
        if pdate(nsd) is not None and pdate(nlp) is not None:
            s = s + ' Bir sonraki hesap kesim tarihiniz ' + sdate(nsd) + ', son ödeme tarihiniz ' + sdate(nlp) + '.'
        s = s + ' ' + S_ONCE_YEAR
        pw = gi('want_week')
        vars['want_week'] = '0'
        full = (pre + ' ' + s).strip()
        if 1 <= pw <= 4 and pw != cw:
            preview(pw, full)
            return
        if pw == cw and pw:
            full = full + ' Kartınız zaten bu haftada, değişiklik gerekmiyor.'
        q = week_options_q()
        ask(full, q, 'Hangi haftayı tercih edersiniz?', 'week_pick')
        return
    if name == 'week_decide':
        pre = g('week_prefix')
        if not ok:
            finish((pre + ' ' + S_WEEK_SVC).strip(), 'agent')
            return
        vars['wk_new_sd'] = str(data.get('statementDate') or '')
        vars['wk_new_due'] = str(data.get('statementDueDate') or data.get('lastPayDate') or '')
        je = joint_effect()
        ask((pre + ' ' + je).strip(), confirm_q(), 'Değişikliği onaylıyor musunuz?', 'week_confirm')
        return
    if name == 'week_change':
        okc = ok and str(data.get('exitState', '')).upper() == 'OK' and str(data.get('responseCode', '0')) in ('0', '0.0', '')
        if not okc:
            finish(S_WEEK_SVC, 'agent')
            return
        vars['week_done'] = '1'
        c = cur()
        s = (intro(c) + 'ın hesap kesim haftası her ayın ' + ORD[gi('wk_new')] + ' haftası olarak değiştirildi. Yeni hesap kesim tarihiniz '
             + sdate(g('wk_new_sd')) + ', son ödeme tarihiniz ' + sdate(g('wk_new_due')) + '.')
        finish(s + ' ' + S_MENU, 'menu')
        return
    if name == 'pdf_send':
        okp = ok and str(data.get('exitState', '')).upper() in ('DONE', 'OK')
        if not okp:
            finish(S_SVC, 'agent')
            return
        vars['sends'] = str(gi('sends') + 1)
        finish(S_SENT + ' ' + S_MENU, 'menu')
        return
    speak(g('last_full'))


def gi_val(x):
    try:
        return int(float(str(x)))
    except Exception:
        return 0


# ---------------------------------------------------------------- user turns
WEEKS = dict(first=1, second=2, third=3, fourth=4)


def ex(k):
    v = g(k).strip()
    if v.lower() in ('', 'none', 'null', 'no', 'calm', 'turkish'):
        return ''
    return v


def reset_extracted():
    for k in ('u_intent', 'u_yesno', 'u_week', 'u_only', 'u_card_text', 'u_digits'):
        vars[k] = 'none'
    vars['u_mood'] = 'calm'
    vars['u_lang'] = 'turkish'
    vars['u_silent'] = 'no'
    vars['u_secret'] = 'no'


def handle_user():
    intent = ex('u_intent')
    yn = ex('u_yesno') if g('u_yesno').strip() not in ('none', '') else ''
    if g('u_yesno').strip() == 'no':
        yn = 'no'
    week = WEEKS.get(ex('u_week'), 0)
    week_other = ex('u_week') == 'other'
    only = ex('u_only')
    text = ex('u_card_text')
    ds = re.sub(r'\D', '', ex('u_digits'))
    mood = g('u_mood').strip()
    lang = g('u_lang').strip()
    silent = g('u_silent').strip() == 'yes'
    secret = g('u_secret').strip() == 'yes'
    reset_extracted()
    stage = g('stage') or 'start'

    if silent and not intent and not yn and not text and not ds and not week:
        n = gi('sil') + 1
        vars['sil'] = str(n)
        if n >= 3:
            finish(S_SILENT_END, 'hangup')
            return
        if stage == 'closing':
            route_end()
            return
        if stage == 'start':
            speak('Kredi kartı ekstre borcunuzla ilgili size nasıl yardımcı olabilirim?')
            return
        speak(g('q_short') or g('last_full'))
        return
    vars['sil'] = '0'

    if lang == 'other':
        finish(S_MENU_A, 'menu')
        return
    if intent == 'agent':
        finish(S_AGENT, 'agent')
        return
    if intent == 'pay':
        finish(S_PAY, 'agent')
        return
    if intent == 'dispute':
        finish(S_DISPUTE, 'agent')
        return
    if intent == 'other_person':
        finish(S_OTHER_PERSON, 'ivr')
        return

    prefix = ''
    if mood == 'angry' or intent == 'complaint':
        n = gi('calm') + 1
        vars['calm'] = str(n)
        if n > 3:
            finish(S_AGENT, 'agent')
            return
        prefix = S_CALM
        if intent == 'complaint':
            if stage == 'closing':
                speak(S_CALM + ' ' + g('last_full'))
                return
            if stage == 'start':
                speak(S_CALM + ' Kredi kartı ekstre borcunuzla ilgili size nasıl yardımcı olabilirim?')
                return
            reask(prefix, count=False)
            return
    if secret:
        prefix = (prefix + ' ' + S_SECRET).strip()

    if stage == 'closing':
        if intent in ('email', 'old_statement') and g('end_kind') == 'menu' and gi('sends') < 3 and g('email_state') != 'fail':
            start_email(prefix)
            return
        if intent == 'week' and g('end_kind') == 'menu' and g('week_done') != '1' and g('last_nodebt') == '1':
            start_week(prefix)
            return
        if intent == 'undo' and g('week_done') == '1':
            finish((prefix + ' Hesap kesim tarihi değişikliğiniz gerçekleşti, bu görüşmede geri alınamıyor. ' + S_MENU).strip(), 'menu')
            return
        if intent == 'when_applies' and g('week_done') == '1':
            finish((prefix + ' Yeni hesap kesim tarihiniz ' + sdate(g('wk_new_sd')) + '. ' + S_MENU).strip(), 'menu')
            return
        if intent == 'week' and g('week_done') == '1':
            finish((prefix + ' Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz ve bu yıl değişiklik yapıldı. ' + S_MENU).strip(), 'menu')
            return
        if intent == 'card_digits':
            finish((prefix + ' ' + S_DIGITS + ' ' + S_MENU).strip(), 'menu')
            return
        if intent == 'repeat':
            speak(g('last_full'))
            return
        route_end()
        return

    if intent == 'card_digits':
        c = cur()
        extra = ''
        if c.get('l4'):
            extra = ' Kartınızın son dört hanesi ' + l4w(c.get('l4')) + '.'
        p = (prefix + ' ' + S_DIGITS + extra).strip()
        if stage == 'start':
            vars['start_prefix'] = p
            go_api('cards_list')
            return
        reask(p, count=False)
        return
    if intent == 'instructions':
        p = (prefix + ' ' + S_INSTR).strip()
        if stage == 'start':
            vars['start_prefix'] = p
            go_api('cards_list')
            return
        reask(p, count=False)
        return
    if intent == 'repeat' and stage != 'start':
        speak((prefix + ' ' + g('last_full')).strip())
        return
    if intent == 'out_of_scope' and stage != 'oos':
        vars['oos_stage'] = stage
        vars['oos_q'] = g('q')
        vars['oos_qs'] = g('q_short')
        vars['oos_tries'] = g('tries')
        vars['oos_cand'] = g('cand_json')
        ask(prefix, S_OOS, 'Sizi ana menüye aktarmamı ister misiniz?', 'oos')
        return

    if stage == 'oos':
        if yn == 'yes':
            finish(S_MENU_A, 'menu')
            return
        if yn == 'no' or intent in ('continue', 'debt', 'email', 'week') or text or ds or week:
            st = g('oos_stage') or 'start'
            vars['stage'] = st
            vars['q'] = g('oos_q')
            vars['q_short'] = g('oos_qs')
            vars['tries'] = g('oos_tries') or '0'
            vars['cand_json'] = g('oos_cand') or '[]'
            if yn == 'no' and not (intent or text or ds or week):
                if st == 'start':
                    vars['stage'] = 'start'
                    speak((prefix + ' Kredi kartı ekstre borcunuzla ilgili size nasıl yardımcı olabilirim?').strip())
                    return
                full = (prefix + ' ' + g('q')).strip()
                vars['last_full'] = full
                speak(full)
                return
            stage = st
        else:
            reask(prefix)
            return

    if only in ('minimum', 'due_date'):
        vars['only'] = only

    if stage == 'start':
        if intent == 'email':
            vars['want'] = 'email'
        elif intent == 'week':
            vars['want'] = 'week'
            if week:
                vars['want_week'] = str(week)
        elif intent == 'old_statement':
            vars['want'] = 'email'
            prefix = (prefix + ' Yalnızca son kesilen ekstrenizi gönderebiliyorum.').strip()
        vars['first_card_text'] = text
        vars['first_digits'] = ds
        vars['start_prefix'] = prefix
        vars['stage'] = 'loading'
        go_api('cards_list')
        return

    if stage in ('pick', 'pick4', 'pick6', 'pickfull'):
        if text or ds:
            if resolve_pick(text, ds, prefix):
                return
        if intent == 'all_cards':
            reask((prefix + ' Borç bilgisini kart kart verebiliyorum.').strip())
            return
        if intent == 'no_card' and stage in ('pick4', 'pick6', 'pickfull'):
            pool = pool_now()
            names = examples(pool)
            vars['tries'] = str(gi('tries') + 1)
            if gi('tries') >= 3:
                finish(S_FAIL3, 'menu')
                return
            reask((prefix + ' Kart numaranızın son hanelerini kartınızın üzerinden ya da mobil uygulamamızdan görebilirsiniz.').strip(), count=False)
            return
        if intent in ('email', 'week'):
            vars['want'] = intent
            if intent == 'week' and week:
                vars['want_week'] = str(week)
            reask((prefix + ' Önce kartınızı belirleyelim.').strip(), count=False)
            return
        if intent == 'nothing_else' or yn == 'no':
            finish((prefix + ' ' + S_MENU).strip(), 'menu')
            return
        reask(prefix)
        return

    if stage == 'another':
        if text or ds:
            vars['cand_json'] = json.dumps([c.get('num') for c in (unread() or eligible())])
            if resolve_pick(text, ds, prefix):
                return
        if yn == 'yes' or intent in ('debt', 'all_cards'):
            ask_pick(prefix, unread() or eligible())
            return
        if yn == 'no' or intent == 'nothing_else':
            after_cards(prefix)
            return
        if intent == 'email':
            start_email(prefix)
            return
        if intent == 'old_statement':
            start_email((prefix + ' Yalnızca son kesilen ekstrenizi gönderebiliyorum.').strip())
            return
        if intent == 'week':
            if week:
                vars['want_week'] = str(week)
            start_week(prefix)
            return
        reask(prefix)
        return

    if stage == 'offer':
        if intent == 'email' or (intent == 'old_statement'):
            p = prefix
            if intent == 'old_statement':
                p = (prefix + ' Yalnızca son kesilen ekstrenizi gönderebiliyorum.').strip()
            if g('email_state') == 'fail':
                finish((p + ' ' + S_SVC).strip(), 'agent')
                return
            start_email(p)
            return
        if intent == 'week' or week:
            if g('week_done') == '1':
                finish((prefix + ' Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz ve bu yıl değişiklik yapıldı. ' + S_MENU).strip(), 'menu')
                return
            if week:
                vars['want_week'] = str(week)
            start_week(prefix)
            return
        if intent in ('debt', 'all_cards') or text or ds:
            if len(eligible()) > 1:
                if text or ds:
                    vars['cand_json'] = json.dumps([c.get('num') for c in eligible()])
                    if resolve_pick(text, ds, prefix):
                        return
                ask_pick(prefix, unread() or eligible())
                return
            speak((prefix + ' ' + g('reading') + ' ' + g('q')).strip())
            return
        if intent == 'nothing_else' or yn == 'no':
            finish((prefix + ' ' + S_MENU).strip(), 'menu')
            return
        if yn == 'yes':
            em = g('email_state') == 'ok'
            if em and g('week_done') != '1':
                reask((prefix + ' Hesap kesim tarihinizi mi değiştirmek istersiniz, yoksa ekstrenizin e-posta ile gönderilmesini mi?').strip(), count=False)
                return
            if em:
                start_email(prefix)
                return
            start_week(prefix)
            return
        if intent in ('other_address', 'not_my_address'):
            handle_address_issue(intent, prefix)
            return
        reask(prefix)
        return

    if stage == 'email_confirm':
        if intent in ('other_address', 'not_my_address'):
            handle_address_issue(intent, prefix)
            return
        if intent == 'old_statement':
            reask((prefix + ' Yalnızca son kesilen ekstrenizi gönderebiliyorum.').strip(), count=False)
            return
        if yn == 'yes':
            vars['req_email'] = g('email_addr')
            vars['req_sd'] = g('stmt_date')
            vars['req_card'] = cur().get('num', '')
            go_api('pdf_send')
            return
        if yn == 'no' or intent == 'nothing_else':
            finish((prefix + ' ' + S_MENU).strip(), 'menu')
            return
        if intent == 'week':
            if week:
                vars['want_week'] = str(week)
            start_week(prefix)
            return
        reask(prefix)
        return

    if stage == 'week_pick':
        if week:
            if week == gi('wk_cur'):
                reask((prefix + ' Kartınızın hesap kesim tarihi zaten her ayın ' + ORD[week] + ' haftası, bu hafta için değişiklik gerekmiyor.').strip(), count=False)
                return
            preview(week, prefix)
            return
        if yn == 'no' or intent == 'nothing_else':
            finish((prefix + ' ' + S_MENU).strip(), 'menu')
            return
        if week_other:
            reask((prefix + ' Hesap kesim tarihini yalnızca hafta olarak seçebilirsiniz.').strip())
            return
        if intent == 'email':
            start_email(prefix)
            return
        reask(prefix)
        return

    if stage == 'week_confirm':
        if week and week != gi('wk_new'):
            if week == gi('wk_cur'):
                reask((prefix + ' Kartınızın hesap kesim tarihi zaten her ayın ' + ORD[week] + ' haftası.').strip(), count=False)
                return
            preview(week, prefix)
            return
        if yn == 'yes':
            if g('week_done') == '1':
                finish(S_MENU, 'menu')
                return
            vars['req_week'] = g('wk_new')
            vars['req_day'] = g('wk_day')
            vars['req_card'] = cur().get('num', '')
            vars['stage'] = 'changing'
            go_api('week_change')
            return
        if yn == 'no' or intent == 'nothing_else':
            finish((prefix + ' Hesap kesim tarihiniz değiştirilmedi. ' + S_MENU).strip(), 'menu')
            return
        reask((prefix + ' Değişikliği yapabilmem için açık bir onayınız gerekiyor.').strip())
        return

    if stage in ('loading', 'changing'):
        speak(g('last_full') or 'Bilgilerinizi kontrol ediyorum.')
        return

    reask(prefix)


def handle_address_issue(intent, prefix):
    if intent == 'not_my_address':
        finish((prefix + ' Bu durumda ekstrenizi gönderemiyorum. E-posta adresinizi bu görüşmede değiştiremiyorum. ' + S_MENU).strip(), 'menu')
        return
    finish((prefix + ' Ekstrenizi yalnızca son kesilen ekstre olarak ve bankamızda kayıtlı e-posta adresinize gönderebiliyorum; '
            'başka bir adrese, kağıt olarak ya da kısa mesajla gönderemiyorum. ' + S_MENU).strip(), 'menu')


def route_end():
    k = g('end_kind') or 'menu'
    if k not in ('menu', 'agent', 'ivr', 'hangup'):
        k = 'menu'
    vars['say'] = ''
    vars['route'] = 'end_' + k


try:
    vars['route'] = 'talk'
    pend = g('pending')
    if pend:
        vars['pending'] = ''
        handle_result(pend)
    else:
        handle_user()
except Exception as e:
    vars['brain_error'] = str(e)[:300]
    vars['say'] = g('last_full') or 'Kredi kartı ekstre borcunuzla ilgili size nasıl yardımcı olabilirim?'
    vars['route'] = 'talk'

